<script setup lang="ts">
/**
 * Numbered page controls for paged lists (`design/components/pagination.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/pagination.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useTemplateRef, watch } from 'vue'

import { PAGINATION_ELLIPSIS, agentMember, paginationWindow } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/pagination.module.css'
import Button from '../controls/Button.vue'
import Inline from '../layout/Inline.vue'

export type SiblingCount = NonNullable<PaginationProps['siblingCount']>

export interface PaginationMessages {
  previous: string
  next: string
  page: (page: number) => string
}

export interface PaginationProps {
  /**
   * The app holds the pager while it does something else to the list: every control is disabled,
   * the current page too, and no page is asked for.
   */
  disabled?: boolean
  label?: string
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: PaginationMessages
  /**
   * 1-based and controlled, because the current page belongs to the list.
   */
  page: number
  pageCount: number
  siblingCount?: 1 | 2
}

defineOptions({ name: 'Pagination', inheritAttrs: false })

const props = withDefaults(defineProps<PaginationProps>(), {
  disabled: false,
  label: 'Pagination',
  messages: () => ({
    previous: 'Previous page',
    next: 'Next page',
    page: (page) => `Page ${page}`,
  }),
  siblingCount: 1,
})
const emit = defineEmits<{ pageChange: [page: number] }>()
const focused = ref(null as HTMLElement | null)
const taken = ref(null as string | number | null)
const root = useTemplateRef<HTMLElement>('root')
const entries = computed(() => paginationWindow(props.page, props.pageCount, props.siblingCount))
const controls = computed(() => [
  'previous',
  ...entries.value.filter((shown) => shown !== PAGINATION_ELLIPSIS),
  'next',
])
const focusIn = computed(() => (event: FocusEvent) => {
  focused.value = event.target as HTMLElement
})
const focusOut = computed(() => (event: FocusEvent) => {
  if (!(event.target as HTMLElement).matches(':disabled')) focused.value = null
})
const keepPlace = computed(() => () => {
  const pager = root.value as HTMLElement | null
  if (pager === null) return
  const names: readonly (string | number)[] = controls.value
  if (!props.disabled) {
    const control = taken.value
    taken.value = null
    if (control === null || document.activeElement !== pager) return
    const button = [...pager.querySelectorAll('button')][names.indexOf(control)]
    if (button !== undefined && !button.matches(':disabled')) button.focus()
    return
  }
  const from = focused.value as HTMLElement | null
  if (from === null || !from.isConnected || !from.matches(':disabled')) return
  const active = document.activeElement
  if (active !== from && active !== null && active !== document.body) return
  taken.value =
    names[[...pager.querySelectorAll('button')].indexOf(from as HTMLButtonElement)] ?? null
  pager.focus()
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const run = () => {
    keepPlace.value()
  }
  const mutation = typeof MutationObserver === 'undefined' ? undefined : new MutationObserver(run)
  for (const element of [root.value])
    if (element)
      mutation?.observe(element, {
        childList: true,
        characterData: true,
        subtree: true,
        attributeFilter: ['disabled'],
      })
  release1 = () => {
    mutation?.disconnect()
  }
  run()
}
onMounted(effect1)
watch(() => entries.value.length > 0, effect1, { flush: 'post' })
onBeforeUnmount(() => release1?.())
const effect2 = () => {
  keepPlace.value()
}
watch(() => props.disabled, effect2, { flush: 'post' })
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = agentMember({
    member: 'Pagination',
    element: () => root.value,
    state: () => ({ page: props.page, 'page-count': props.pageCount, disabled: props.disabled }),
    actions: {
      set: {
        argument: 'number',
        run: (value) =>
          (() => {
            if (!Number.isInteger(value) || value < 1 || value > props.pageCount) {
              throw new Error(
                `There is no page ${value}; the pages run from 1 to ${props.pageCount}.`,
              )
            }
            if (value !== props.page) emit('pageChange', value)
          })(),
      },
    },
    withholds: () => root.value,
  })
  release3 = () => {
    ran()
  }
}
onMounted(effect3)
onBeforeUnmount(() => release3?.())
</script>

<template>
  <nav
    v-if="entries.length > 0"
    ref="root"
    :class="styles.pagination"
    :aria-label="label"
    :data-disabled="disabled ? '' : undefined"
    tabindex="-1"
    data-member="pagination"
    @focusin="focusIn($event)"
    @focusout="focusOut($event)"
  >
    <Inline :gap="1" align="center" :wrap="true">
      <Button
        variant="ghost"
        tone="neutral"
        size="sm"
        :iconOnly="true"
        icon="previous"
        :label="messages.previous"
        :disabled="disabled || page <= 1"
        @click="emit('pageChange', page - 1)"
      />
      <template
        v-for="(entry, at) in entries"
        :key="entry === PAGINATION_ELLIPSIS ? `gap-${at}` : entry"
      >
        <span v-if="entry === PAGINATION_ELLIPSIS" :class="styles.ellipsis" aria-hidden="true">
          …
        </span>
        <Button
          v-else
          :variant="entry === page ? 'soft' : 'ghost'"
          :tone="entry === page ? 'accent' : 'neutral'"
          size="sm"
          :current="entry === page"
          :label="String(entry)"
          :aria-label="messages.page(entry)"
          :disabled="disabled"
          @click="entry !== page && emit('pageChange', entry)"
        />
      </template>
      <Button
        variant="ghost"
        tone="neutral"
        size="sm"
        :iconOnly="true"
        icon="next"
        :label="messages.next"
        :disabled="disabled || page >= pageCount"
        @click="emit('pageChange', page + 1)"
      />
    </Inline>
  </nav>
</template>
